class Coordenada:
    def __init__(self, x: float, y: float):
        self.x, self.y = x, y

    def __repr__(self) -> str:
        return f'Coordenada(x={self.x}, y={self.y})'  # Inequívoco para devs

    def __str__(self) -> str:
        return f'({self.x}, {self.y})'                 # Amigable para el usuario

